  font-size: 12px;
  font-weight: 700;
  text-shadow: 0 1px 0 rgba(255,255,255,.85);
  z-index: 2;
  white-space: nowrap;
  pointer-events: none;
}

/*
  地图上的点位图标。
  每一个 marker 都由 JS 根据 POINTS 数据动态创建。
  marker 的 left/top 对应点位数据里的 x/y。
*/
.marker {
  position: absolute;
  z-index: 6;
  width: 42px;
  height: 42px;
  border: 0;
  padding: 0;
  border-radius: 50% 50% 50% 8px;
  transform: translate(-50%, -100%) rotate(-45deg);
  display: grid;
  place-items: center;
  color: #fff;
  box-shadow: 0 12px 22px rgba(96, 61, 35, .24), inset 0 0 0 3px rgba(255,255,255,.45);
  cursor: pointer;
  transition: transform .18s ease, filter .18s ease;
}
.marker span {
  transform: rotate(45deg);
  font-size: 18px;
}
.marker.active {
  transform: translate(-50%, -100%) rotate(-45deg) scale(1.18);
  filter: saturate(1.08);
}
.marker.active::before {
  content: "";
  position: absolute;
  inset: -18px;
  border-radius: 50%;
  background: rgba(238, 87, 35, .18);
  z-index: -1;
  animation: pulse 1.3s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% { transform: scale(.88); opacity: .8; }
  50% { transform: scale(1.18); opacity: .35; }
}

.locate-btn {
  position: absolute;
  left: 16px;
  bottom: 204px;
  z-index: 8;
  width: 46px;
  height: 46px;
  border: 0;
  border-radius: 18px;
  background: #fff;
  font-size: 22px;
  box-shadow: var(--shadow-soft);
  cursor: pointer;
}

/*
  地图底部弹出的点位信息卡片。
  点击不同地图点位时，JS 会重新渲染这里的名称、简介、地址、电话和导航按钮。
*/
.sheet {
  position: relative;
  left: auto;
  right: auto;
  bottom: auto;
  z-index: 10;
  min-height: 158px;
  margin: 12px 12px 9px;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  backdrop-filter: none;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(12px);
  transition: transform .28s cubic-bezier(.22, .8, .24, 1), opacity .2s ease, visibility .2s ease;
}
.sheet.is-open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0);
}

/* 点位头部信息 */
