.route-video-entry {
  display: grid;
  grid-template-columns: 112px minmax(0, 1fr) 12px;
  align-items: center;
  gap: 12px;
  width: 100%;
  margin-top: 20px;
  padding: 12px;
  border: 1px solid #e5e9dc;
  border-radius: 20px;
  background: linear-gradient(110deg, #f4f8ee, #fffaf1);
  color: #384b3a;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.route-video-entry:hover { border-color: #9bb694; }
.route-video-entry:focus-visible { outline: 3px solid #65916c; outline-offset: 3px; }
.route-video-thumb { position: relative; overflow: hidden; border-radius: 13px; height: 94px; }
.route-video-thumb img { display: block; width: 100%; height: 100%; object-fit: cover; }
.route-video-play {
  position: absolute; inset: 0; margin: auto; display: grid; place-items: center;
  width: 34px; height: 34px; padding-left: 2px; border-radius: 50%;
  background: rgba(255,255,255,.93); color: #528269; font-size: 14px;
}
.route-video-copy { display: grid; justify-items: start; gap: 4px; min-width: 0; }
.route-video-kicker { color: #69836a; font-size: 10px; }
.route-video-copy strong { font-size: 15px; line-height: 1.4; }
.route-video-description { color: #7a8272; font-size: 11px; line-height: 1.4; }
.route-video-status { margin-top: 2px; padding: 3px 8px; border-radius: 999px; background: #e5eedf; color: #577153; font-size: 10px; }
.route-video-arrow { color: #8a9b82; font-size: 22px; }
@media (max-width: 374px) {
  .route-video-entry { grid-template-columns: 88px minmax(0, 1fr) 10px; gap: 9px; padding: 10px; }
  .route-video-copy strong { font-size: 14px; }
}

.activity-video-list { display: grid; gap: 10px; }
.activity-registration-list { display: grid; gap: 10px; }
.activity-video-item {
  display: grid;
  grid-template-columns: 62px minmax(0, 1fr) auto 16px;
  gap: 10px;
  align-items: center;
  width: 100%;
  min-height: 74px;
  padding: 10px;
  border: 1px solid #f0e1d2;
  border-radius: 18px;
  color: #382a22;
  background: rgba(255,255,255,.88);
  box-shadow: var(--shadow-soft);
  font: inherit;
  text-decoration: none;
  text-align: left;
  cursor: pointer;
  transition: transform .16s ease, box-shadow .16s ease;
}
.activity-video-item:hover { transform: translateY(-2px); box-shadow: var(--shadow); }
.activity-history .activity-video-item {
  grid-template-columns: 88px minmax(0, 1fr) 16px;
  min-height: 70px;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 16px;
  background: linear-gradient(110deg, #fff, #fff9f2);
  box-shadow: 0 3px 12px rgba(76, 62, 46, .05);
}
.activity-history-thumb {
  position: relative;
  display: block;
  width: 88px;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  border-radius: 10px;
  background: #eee4d8;
}
.activity-history-thumb img { display: block; width: 100%; height: 100%; object-fit: cover; }
.activity-history-thumb > span {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  padding-left: 2px;
  border: 1px solid rgba(255,255,255,.7);
  border-radius: 50%;
  color: #fff;
  background: rgba(32,27,22,.5);
  font-size: 10px;
}
.activity-history .activity-video-copy strong { white-space: normal; line-height: 1.4; }
.activity-history .activity-video-copy small { margin-top: 3px; font-size: 10px; }
.activity-history .activity-video-item:focus-visible { outline: 3px solid #e77c43; outline-offset: 3px; }
.activity-video-date {
  display: grid;
  place-items: center;
  min-height: 54px;
  padding: 6px;
  border-radius: 14px;
  color: #e85b28;
  background: #fff0e5;
  text-align: center;
}
.activity-video-date strong { font-size: 14px; line-height: 1.1; }
.activity-video-date small { margin-top: 3px; font-size: 9px; }
.activity-video-copy { min-width: 0; }
.activity-video-copy strong { display: block; overflow: hidden; font-size: 14px; white-space: nowrap; text-overflow: ellipsis; }
.activity-video-copy small { display: block; margin-top: 6px; overflow: hidden; color: #89766a; font-size: 9px; white-space: nowrap; text-overflow: ellipsis; }
.activity-video-duration { color: #a08d80; font-size: 10px; }
.activity-video-arrow { color: #a28f81; font-size: 22px; line-height: 1; }
.activity-registration-item {
  border-color: rgba(236, 145, 54, .2);
  background: linear-gradient(110deg, rgba(255,255,255,.96), rgba(255,247,232,.96));
}
.activity-registration-status {
  padding: 5px 8px;
  border-radius: 999px;
  color: #cb6b27;
  background: #fff0dd;
  font-size: 9px;
  font-weight: 800;
  white-space: nowrap;
}

.activity-note {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 18px;
  padding: 14px 16px;
  border: 1px solid rgba(240, 174, 82, .26);
  border-radius: 20px;
  background: linear-gradient(110deg, #fff0dc, #fff8e9);
}
.activity-note > span {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  color: #fff;
  background: linear-gradient(145deg, #ff9c35, #ed5927);
}
.activity-note p { margin: 0; color: #795f4f; font-size: 10px; line-height: 1.55; }
.activity-note strong { color: #473329; font-size: 12px; }

.activity-contribute {
  position: relative;
  display: grid;
  grid-template-columns: 112px minmax(0, 1fr);
  gap: 14px;
  align-items: center;
  margin-top: 18px;
  overflow: hidden;
  padding: 16px 18px 11px;
  border: 1px solid rgba(238, 110, 47, .14);
  border-radius: 25px;
  background:
    radial-gradient(circle at 0 0, rgba(255,255,255,.82), transparent 38%),
    linear-gradient(135deg, #fff1db 0%, #ffe4ca 52%, #ffd8bd 100%);
  box-shadow: 0 12px 28px rgba(139, 82, 45, .12);
}
.activity-contribute::after {
  content: "";
  position: absolute;
  right: -30px;
  top: -38px;
  width: 110px;
  height: 110px;
  border: 22px solid rgba(255,255,255,.24);
  border-radius: 50%;
  pointer-events: none;
}
.activity-contribute-visual {
  position: relative;
  align-self: stretch;
  min-height: 128px;
}
.activity-contribute-photo {
  position: absolute;
  display: block;
  width: 72px;
  height: 94px;
  border: 4px solid #fffaf5;
  border-bottom-width: 14px;
  border-radius: 12px;
  background-color: #c98a62;
  background-size: cover;
  background-position: center;
  box-shadow: 0 10px 22px rgba(95, 56, 34, .2);
}
.activity-contribute-photo-back {
  left: 3px;
  top: 5px;
  background-image: url("assets/routes/binjiang/stop-park.webp");
  transform: rotate(-8deg);
}
.activity-contribute-photo-front {
  right: 2px;
  bottom: 4px;
  z-index: 1;
  background-image: url("assets/routes/binjiang/highlight-photo.webp");
  transform: rotate(7deg);
}
.activity-contribute-camera {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 3px solid rgba(255,255,255,.9);
  border-radius: 50%;
  color: #fff;
  background: linear-gradient(145deg, #ff8b3e, #ed5729);
  box-shadow: 0 8px 18px rgba(169, 69, 29, .28);
  transform: translate(-50%, -42%);
}
.activity-contribute-camera svg { width: 18px; fill: currentColor; }
.activity-contribute-copy { position: relative; z-index: 1; min-width: 0; }
.activity-contribute-kicker {
  color: #d95c29;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .08em;
}
.activity-contribute-copy h3 {
  margin: 5px 0 7px;
  color: #402b20;
  font-size: 18px;
  line-height: 1.22;
}
.activity-contribute-copy p {
  margin: 0;
  color: #826554;
  font-size: 10px;
  line-height: 1.55;
}
.activity-contribute-button {
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 18px;
  margin-top: 9px;
  padding: 9px 12px 9px 14px;
  border: 0;
  border-radius: 999px;
  color: #fff;
  background: linear-gradient(135deg, #f77334, #e64e24);
  box-shadow: 0 8px 16px rgba(213, 78, 31, .22);
  font: 800 11px/1 var(--font);
  cursor: pointer;
  transition: transform .16s ease, box-shadow .16s ease;
}
.activity-contribute-button:hover { transform: translateY(-1px); box-shadow: 0 10px 20px rgba(213, 78, 31, .28); }
.activity-contribute-button:active { transform: scale(.98); }
.activity-contribute-button > span:last-child { font-size: 20px; font-weight: 400; line-height: .7; }
.activity-contribute-note {
  position: relative;
  z-index: 1;
  grid-column: 1 / -1;
  margin: 1px 0 0;
  padding-top: 8px;
  border-top: 1px solid rgba(163, 97, 57, .12);
  color: #8c6a57;
  font-size: 8px;
  line-height: 1.5;
}
.activity-contribute-note span { color: #4f955a; font-weight: 900; }

body.activity-upload-open,
body.activity-video-open,
body.activity-album-open,
body.activity-photo-open { overflow: hidden; }

.activity-upload-lightbox[hidden] { display: none; }
.activity-upload-lightbox {
  position: fixed;
  inset: 0;
  z-index: 9997;
  display: grid;
  place-items: center;
  padding: 18px;
}
.activity-upload-backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  background: rgba(39, 26, 19, .72);
  backdrop-filter: blur(9px);
  cursor: zoom-out;
}
.activity-upload-dialog {
  position: relative;
  z-index: 1;
  width: min(520px, 100%);
  max-height: min(92vh, 820px);
  overflow: auto;
  padding: 20px;
  border: 1px solid rgba(255,255,255,.72);
  border-radius: 26px;
  background: #fffaf5;
  box-shadow: 0 26px 74px rgba(34, 21, 14, .36);
  overscroll-behavior: contain;
}
.activity-upload-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 17px;
}
.activity-upload-head small {
  color: #e3602c;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .12em;
}
.activity-upload-head h2 {
  margin: 3px 0 5px;
  color: #39281f;
  font-size: 24px;
  line-height: 1.2;
}
.activity-upload-head p {
  margin: 0;
  color: #897367;
  font-size: 10px;
  line-height: 1.5;
}
.activity-upload-kingsoft {
  display: grid;
  justify-items: center;
  gap: 11px;
}
.activity-upload-qr-card {
  width: min(220px, 62vw);
  aspect-ratio: 1;
  overflow: hidden;
  border: 1px solid #eee4dc;
  border-radius: 19px;
  background: #fff;
  box-shadow: 0 10px 26px rgba(75, 48, 32, .11);
}
.activity-upload-qr-card img {
  display: block;
  width: 170%;
  max-width: none;
  height: auto;
  transform: translate(-20.5%, -24.5%);
}
.activity-upload-guide {
  display: grid;
  gap: 3px;
  color: #816b5e;
  text-align: center;
}
.activity-upload-guide strong {
  color: #4a352a;
  font-size: 13px;
}
.activity-upload-guide span {
  font-size: 9px;
  line-height: 1.5;
}
.activity-upload-close {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 38px;
  height: 38px;
  padding: 0;
  border: 1px solid #ead9cb;
  border-radius: 50%;
  color: #70594b;
  background: #fff;
  font: 300 27px/1 Arial, sans-serif;
  cursor: pointer;
}
.activity-upload-form { display: grid; gap: 14px; }
.activity-upload-field { position: relative; display: grid; gap: 7px; }
.activity-upload-field > span:first-child {
  display: flex;
  align-items: baseline;
  gap: 7px;
  color: #4a362b;
  font-size: 12px;
  font-weight: 800;
}
.activity-upload-field > span em {
  color: #e75d2a;
  font-size: 8px;
  font-style: normal;
  font-weight: 800;
}
.activity-upload-field > span small {
  color: #9a887c;
  font-size: 8px;
  font-weight: 500;
}
.activity-upload-field select,
.activity-upload-field input[type="text"],
.activity-upload-field textarea {
  width: 100%;
  border: 1px solid #eaded4;
  border-radius: 13px;
  outline: none;
  color: #44332a;
  background: #fff;
  font: 12px/1.45 var(--font);
  transition: border-color .16s ease, box-shadow .16s ease;
}
.activity-upload-field select,
.activity-upload-field input[type="text"] { height: 43px; padding: 0 12px; }
.activity-upload-field textarea { min-height: 76px; padding: 11px 12px 22px; resize: vertical; }
.activity-upload-field select:focus,
.activity-upload-field input[type="text"]:focus,
.activity-upload-field textarea:focus {
  border-color: #ef8a59;
  box-shadow: 0 0 0 3px rgba(239, 105, 48, .1);
}
.activity-upload-picker {
  display: grid;
  place-items: center;
  min-height: 116px;
  padding: 16px;
  border: 1.5px dashed #e5b28e;
  border-radius: 17px;
  color: #684b3b;
  background: linear-gradient(145deg, #fff9f1, #fff0e2);
  text-align: center;
  cursor: pointer;
  transition: border-color .16s ease, background .16s ease, transform .16s ease;
}
.activity-upload-picker:hover,
.activity-upload-picker.is-dragging { border-color: #ed6e34; background: #fff0df; transform: translateY(-1px); }
.activity-upload-picker input { position: absolute; width: 1px; height: 1px; overflow: hidden; opacity: 0; }
.activity-upload-picker-icon {
  display: grid;
  place-items: center;
  width: 37px;
  height: 37px;
  margin-bottom: 7px;
  border-radius: 50%;
  color: #fff;
  background: linear-gradient(145deg, #ff9148, #ed5a28);
  box-shadow: 0 7px 15px rgba(226, 91, 37, .2);
}
.activity-upload-picker-icon svg { width: 18px; fill: currentColor; }
.activity-upload-picker strong { font-size: 12px; }
.activity-upload-picker > small { margin-top: 4px; color: #9a8273; font-size: 8px; }
.activity-upload-previews:empty { display: none; }
.activity-upload-previews {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}
.activity-upload-preview {
  position: relative;
  overflow: hidden;
  aspect-ratio: 1;
  border-radius: 13px;
  background: #eee5dc;
  box-shadow: 0 4px 11px rgba(75, 48, 32, .1);
}
.activity-upload-preview img { display: block; width: 100%; height: 100%; object-fit: cover; }
.activity-upload-preview.is-unpreviewable::before {
  content: "图片已选择";
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 8px;
  color: #8d7769;
  background: #f2e9e1;
  font-size: 9px;
  text-align: center;
}
.activity-upload-preview.is-unpreviewable img { opacity: 0; }
.activity-upload-preview button {
  position: absolute;
  right: 5px;
  top: 5px;
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  padding: 0;
  border: 1px solid rgba(255,255,255,.52);
  border-radius: 50%;
  color: #fff;
  background: rgba(42, 31, 25, .72);
  font: 700 17px/1 Arial, sans-serif;
  cursor: pointer;
}
.activity-upload-counter { position: absolute; right: 10px; bottom: 7px; color: #a39287; font-size: 8px; }
.activity-upload-consent {
  display: grid;
  grid-template-columns: 19px minmax(0, 1fr);
  gap: 9px;
  align-items: start;
  color: #725d51;
  font-size: 9px;
  line-height: 1.55;
  cursor: pointer;
}
.activity-upload-consent input { width: 17px; height: 17px; margin: 0; accent-color: #ed642d; }
.activity-upload-status {
  margin: 0;
  padding: 10px 12px;
  border-radius: 12px;
  color: #85552f;
  background: #fff0dd;
  font-size: 9px;
  line-height: 1.5;
}
.activity-upload-status.is-error { color: #a13f2d; background: #ffebe6; }
.activity-upload-status.is-success { color: #3f7748; background: #eaf6e8; }
.activity-upload-submit {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  min-height: 45px;
  padding: 11px 16px;
  border: 0;
  border-radius: 14px;
  color: #fff;
  background: linear-gradient(135deg, #f47d3d, #e95425);
  box-shadow: 0 9px 20px rgba(214, 86, 35, .2);
  font: 800 13px/1 var(--font);
  text-decoration: none;
  cursor: pointer;
}
.activity-upload-submit span:last-child { font-size: 20px; }
.activity-upload-submit:disabled { color: #b7aaa2; background: #e9e3de; box-shadow: none; cursor: not-allowed; }
.activity-upload-privacy { margin: -5px 0 0; color: #a18d80; font-size: 8px; line-height: 1.5; text-align: center; }

