  text-align: center;
}
.activity-photo-lightbox[hidden] { display: none; }
.activity-photo-lightbox {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  place-items: center;
  padding: 20px;
}
.activity-photo-backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  background: rgba(24, 18, 15, .9);
  backdrop-filter: blur(10px);
  cursor: zoom-out;
}
.activity-photo-dialog {
  position: relative;
  z-index: 1;
  width: min(100%, 760px);
  margin: 0;
}
.activity-photo-dialog img {
  display: block;
  width: 100%;
  max-height: 78vh;
  border-radius: 20px;
  background: #2b241f;
  box-shadow: 0 22px 54px rgba(0,0,0,.38);
  object-fit: contain;
}
.activity-photo-dialog figcaption {
  padding-top: 13px;
  color: #fff;
  font-size: 14px;
  font-weight: 800;
  text-align: center;
}
.activity-photo-close {
  position: absolute;
  right: -8px;
  top: -48px;
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  padding: 0;
  border: 1px solid rgba(255,255,255,.34);
  border-radius: 50%;
  color: #fff;
  background: rgba(255,255,255,.12);
  font: 300 27px/1 Arial, sans-serif;
  cursor: pointer;
}

@media (max-width: 640px) {
  .activity-upload-lightbox { align-items: end; padding: 0; }
  .activity-upload-dialog {
    width: 100%;
    max-height: 92vh;
    padding: 18px 16px calc(18px + var(--safe-bottom));
    border-radius: 24px 24px 0 0;
  }
  .activity-upload-head { margin-bottom: 14px; }
  .activity-upload-head h2 { font-size: 22px; }
  .activity-video-lightbox { padding: 10px; }
  .activity-video-dialog { border-radius: 19px; }
  .activity-video-dialog-head { padding: 11px 12px; }
  .activity-video-dialog-head h2 { font-size: 14px; }
  .activity-video-dialog video { max-height: 70vh; }
  .activity-album-lightbox { padding: 10px; }
  .activity-album-dialog {
    max-height: 92vh;
    padding: 17px 13px;
    border-radius: 22px;
  }
  .activity-album-head { margin-bottom: 14px; padding-inline: 3px; }
  .activity-album-head h2 { font-size: 22px; }
  .activity-album-grid { column-count: 2; column-gap: 9px; }
  .activity-album-photo { margin-bottom: 9px; border-radius: 14px; }
}

@media (max-width: 374px) {
  .activity-header { align-items: start; padding-inline: 2px; }
  .activity-header h2 { font-size: 26px; }
  .activity-header p { font-size: 11px; }
  .activity-header-tag { padding: 7px 9px; font-size: 10px; }
  .activity-feature { min-height: 224px; }
  .activity-moments { grid-template-rows: repeat(2, 68px); gap: 7px; }
  .activity-video-item { grid-template-columns: 56px minmax(0, 1fr) auto 12px; gap: 8px; padding: 9px; }
  .activity-video-duration { display: none; }
  .activity-contribute { grid-template-columns: 98px minmax(0, 1fr); gap: 11px; padding: 14px 14px 10px; }
  .activity-contribute-visual { min-height: 118px; }
  .activity-contribute-photo { width: 66px; height: 86px; }
  .activity-contribute-copy h3 { font-size: 18px; }
}

beforeJs:
/**
 * ==============================
 * 三、JavaScript 交互逻辑区
 * ==============================
 * JavaScript 负责“能不能点、点了以后发生什么”。
 *
 * 本文件的运行逻辑可以简单理解为：
 * 1. 先准备数据：分类 CATEGORIES、点位 POINTS、电话 CONTACTS。
 * 2. 页面打开时执行 init()。
 * 3. init() 根据数据自动生成快捷入口、筛选按钮、地图点位、列表卡片和电话卡片。
 * 4. 用户点击按钮时，调用 setView() 切换页面，或调用 renderRealMap()/renderList() 刷新内容。
 *
 * 使用说明：
 * 1. 直接把本文件保存为 index.html，双击即可打开。
 * 2. 点位数据统一维护在 points-data.js，可按实际点位修改名称、地址、电话、经纬度等。
 * 3. 地图优先使用 points-data.js 中的 lng/lat；没有坐标时会通过高德地址解析自动补齐。
 * 4. 高德 Key 与安全配置统一放在 amap.config.js 中。
 */

/*
  CATEGORIES：点位分类配置。

  key   ：程序内部使用的分类代码，不建议随便改。
  label ：筛选按钮上显示的短名称，例如“便民”。
  full  ：卡片上显示的完整名称，例如“便民服务”。
  icon  ：首页快捷入口和分类图标。
  color ：这一类点位的主题颜色。
*/
const CATEGORIES = [
  { key: 'all', label: '全部', icon: '◎', color: '#f2672a' },
  { key: 'service', label: '便民', full: '便民服务', icon: '👥', color: '#f2672a' },
  { key: 'shopping', label: '购物', full: '生活购物', icon: '🛒', color: '#f59d32' },
  { key: 'leisure', label: '休闲', full: '休闲游玩', icon: '🌳', color: '#78aa63' },
  { key: 'memory', label: '记忆', full: '多稼记忆', icon: '🏛️', color: '#a85e48' },
  { key: 'bussiness', label: '商务', full: '商务办公', icon: '🏢', color: '#527da8' }
];

/*
  POINTS：由 points-data.js 提供的全站点位数据。

  后续维护“稼享指南”点位时，主要修改 points-data.js。
  每一个 { ... } 代表一个点位。

  字段说明：
  id       ：点位唯一编号，英文即可，不能重复。
  name     ：点位名称。
  category ：点位分类，要对应 CATEGORIES 里的 key，例如 service / shopping / leisure / memory / bussiness。
  icon     ：点位图标，可以用 emoji，也可以后续换成图片图标。
  intro    ：一句话简介。
  address  ：地址。
  phone    ：电话，没有电话可以写“无”。
  hours    ：开放时间或服务时间。
  lng/lat  ：人工确认的高德 GCJ-02 坐标；未确认时保持 null。
  baiduLng/baiduLat：人工确认的百度 BD-09 坐标；未确认时保持 null。
  x/y      ：示意地图上的位置，范围 0-100；x 越大越靠右，y 越大越靠下。
*/

/*
  POINTS：由 points-data.js 中的 window.POINTS_DATA 生成。
  地图热点、列表搜索、详情卡片和高德导航都读取这一份数据。
  lng/lat：高德 GCJ-02 坐标。人工确认后把 null 换成数字；没有时才按 address 自动解析并缓存。
  baiduLng/baiduLat：百度 BD-09 坐标预留字段，不可直接复制高德坐标。
  x/y 与 hitSize 仅作为旧版图片地图的数据保留，不再控制真实地图的位置。
*/
const POINTS_SOURCE = Array.isArray(window.POINTS_DATA) ? window.POINTS_DATA : [];
const POINTS = POINTS_SOURCE.map(point => ({
  icon: CATEGORIES.find(category => category.key === point.category)?.icon || '⌖',
  intro: '提供地点位置、地址与导航信息。',
  phone: '无',
  hours: '开放或服务时间请以现场公告为准',
  ...point
}));

/*
  旧版图片地图校准开关（真实高德地图不再使用）：
  true  = 显示拖动、坐标和点击范围工具；
  false = 恢复普通访客看到的地图。
  校准完成并把数据复制回 points-data.js 后，请改成 false。
*/
const MAP_CALIBRATION_MODE = false;
const MAP_CALIBRATION_STORAGE_KEY = 'jiaxiang-map-calibration-v1';
let calibrationSelectedId = POINTS[0]?.id || null;

/*
  真实高德地图配置与运行状态。
  正式地图的 Key / 安全密钥请填写在 amap.config.js，不要写进 points-data.js。
*/
const DUOJIA_CENTER_POINT_ID = 'duojia-committee';
// 只控制“一键导航”打开哪家地图；页面内嵌底图仍使用高德。
const NAVIGATION_MAP_PROVIDER = 'amap'; // 可改为 'baidu'
const AMAP_FALLBACK_CENTER = [121.5004, 31.2111];
// v3 会忽略此前可能已经错位的 v2 地址解析缓存。
const AMAP_GEOCODE_STORAGE_KEY = 'jiaxiang-amap-geocodes-v3';
const AMAP_LOADER_URL = 'https://webapi.amap.com/loader.js';
const BINJIANG_ROUTE_MODE = 'binjiang-route';
const BINJIANG_ROUTE_COLOR = '#64ac5e';
const BINJIANG_ROUTE_POINT_IDS = [
  'huangpu-riverside',
  'dongjiadu-flower-bridge',
  'dongjiadu-road-ferry',
  'ferry-space'
];
// 北段沿江边步道经过花桥东侧；2 号点以示意虚线接入，不让主线折回内侧。
const BINJIANG_WATERFRONT_PATH = [
  [121.50782, 31.21637],
  [121.50793, 31.21576],
  [121.50808, 31.21472],
  [121.50814, 31.21385],
  [121.50799, 31.21291],
  [121.50755, 31.21203]
];
const BINJIANG_FLOWER_BRIDGE_SPUR = [
  [121.5070, 31.21389],
  BINJIANG_WATERFRONT_PATH[3]
];
const amapRuntime = {
  api: null,
  map: null,
  markers: new Map(),
  routeLine: null,
  routeSpur: [],
  routeRequestId: 0,
  routePath: null,
  loadPromise: null,
  coordinatesReady: false,
  fallbackCount: 0
};

/*
  CONTACTS：便民电话页的数据。
  如果只想增加、删除或修改电话号码，改这里即可。
*/
const CONTACTS = [
  { name: '多稼居民委员会', desc: '社区咨询、活动报名、便民联系', phone: '021-3376 6298', icon: '👥', color: '#f2672a' },
  { name: '社区卫生服务中心', desc: '基础医疗、健康咨询、慢病随访', phone: '021-6377 0202', icon: '✚', color: '#5fae78' },
  {
    id: 'property-service',
    name: '物业服务电话',
    desc: '报修、门禁、公共区域维护',
    phones: [
      { name: '海珀外滩物业', displayPhone: '（021）63327768', phone: '02163327768' },
      { name: '浦江公寓物业', displayPhone: '（021）63269067', phone: '02163269067' }
    ],
    icon: '🛠️',
    color: '#5b91ca'
  },
  { name: '小东门派出所', desc: '报警求助、户籍咨询及社区安全服务', phone: '021-2303 4720', icon: '👮', color: '#416e9d' },
  { name: '街道服务热线', desc: '综合咨询与为民服务联系', phone: '021-6332 5638', icon: '☎', color: '#a85e48' }
];

/*
  state：页面当前状态。

  view       ：当前显示哪个页面，home/map/list/phone。
  category   ：当前筛选的分类，all 表示全部。
  selectedId ：地图页当前选中的点位 id。
  search     ：列表页搜索框里的关键词。

  你可以把 state 理解为“网页当前记住的状态”。
*/
const state = {
  view: 'home',
  category: 'all',
  selectedId: 'duojia-committee',
  search: '',
  mapMode: null,
  mapReturnView: 'home',
  listReturnView: 'home'
};

/*
  下面两个是简写工具函数：
  $('选择器')  ：找到第一个匹配的元素。
  $$('选择器') ：找到所有匹配的元素，并转成数组。

  例如：
  $('#toast') 相当于 document.querySelector('#toast')。
*/
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => Array.from(root.querySelectorAll(selector));

// 根据分类 key 找到对应分类信息，例如 service -> 便民服务。
function getCategory(key) {
  return CATEGORIES.find(c => c.key === key) || CATEGORIES[0];
}

// points-data.js 中设置 isNew: true 后，在列表、地图卡片和地图标记上显示“新增”。
function renderNewPointBadge(point) {
  return point?.isNew ? '<span class="new-point-badge">新增</span>' : '';
}

// 根据点位 id 找到对应点位信息，例如 duojia-jwh -> 多稼居民委员会。
function getPoint(id) {
  return POINTS.find(p => p.id === id) || POINTS[0];
}

function getVisibleMapPoints() {
  if (state.mapMode === BINJIANG_ROUTE_MODE) {
    return BINJIANG_ROUTE_POINT_IDS
      .map(id => POINTS.find(point => point.id === id))
      .filter(Boolean);
  }
  return POINTS.filter(point => state.category === 'all' || point.category === state.category);
}

/*
  一键导航函数。
  点击“导航前往”后，根据 NAVIGATION_MAP_PROVIDER 拼接高德或百度地图 URI。
  默认使用高德；以后可把配置改成 baidu。
*/
function navigateToPoint(point) {
  if (!point) return;
  showToast(`正在打开${point.name}`);
  window.location.href = NAVIGATION_MAP_PROVIDER === 'baidu'
    ? buildBaiduMapUrl(point)
    : buildAmapUrl(point);
}

// 页面底部黑色提示条，例如点击“我的”时弹出的说明。
function showToast(text) {
  const toast = $('#toast');
  toast.textContent = text;
  toast.classList.add('show');
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => toast.classList.remove('show'), 2400);
}

function setupMoreRoutesDialog() {
  const lightbox = $('#moreRoutesLightbox');
  const openButton = $('[data-more-routes]');
  if (!lightbox || !openButton) return;
  let opener = null;

  const closeDialog = () => {
    if (lightbox.hidden) return;
    lightbox.hidden = true;
    document.body.classList.remove('more-routes-open');
    opener?.focus();
  };

  openButton.addEventListener('click', () => {
    opener = openButton;
    lightbox.hidden = false;
    document.body.classList.add('more-routes-open');
    $('[data-more-routes-close]:last-child', lightbox)?.focus();
  });
  $$('[data-more-routes-close]', lightbox).forEach(button => button.addEventListener('click', closeDialog));
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && !lightbox.hidden) closeDialog();
  });
}

/*
  切换页面函数。
  例如 setView('map') 就会显示地图页，隐藏其他页面。
  核心原理：给目标 section 添加 active 类，其他 section 去掉 active 类。
*/
function setView(view) {
  const enteringMap = view === 'map' && state.view !== 'map';
  state.view = view;
  const activeNavView = ['route', 'guide'].includes(view) ? 'home' : view;
  $$('.view').forEach(v => v.classList.toggle('active', v.dataset.view === view));
  $$('.nav-item').forEach(item => item.classList.toggle('active', item.dataset.go === activeNavView));
  if (view === 'map') renderRealMap({ resetCenter: enteringMap });
  if (view === 'list') renderList();
  if (view === 'phone') renderContacts();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

/*
  切换分类筛选。
  category 可以是 all/service/shopping/leisure/memory。
  地图页和列表页都会用到这个函数。
*/
function setCategory(category, targetView = state.view) {
  state.category = category;
  if (targetView === 'map') state.mapMode = null;
  if (targetView === 'map') renderRealMap();
  if (targetView === 'list') renderList();
}

/*
  渲染首页各类点位的快捷入口。
  这些入口根据 CATEGORIES 自动生成，所以你改 CATEGORIES 后，这里会自动跟着变。
*/
function renderQuickEntries() {
  const quicks = CATEGORIES.filter(c => c.key !== 'all');
  $('#quickEntries').innerHTML = quicks.map(c => `
    <button class="quick-item" data-quick="${c.key}">
      <span class="quick-icon" style="background:${c.color}">${c.icon}</span>
      <span class="quick-label">${c.full}</span>
    </button>
  `).join('');

  $$('#quickEntries .quick-item').forEach(btn => {
    btn.addEventListener('click', () => {
      state.category = btn.dataset.quick;
      state.listReturnView = 'home';
      setView('list');
    });
  });
}

/*
  渲染分类筛选按钮。
  地图页和列表页各有一组筛选按钮，这个函数会同时更新两处。
*/
function renderFilterRows() {
  const isBinjiangRoute = state.mapMode === BINJIANG_ROUTE_MODE;
  const mapCategoryHtml = CATEGORIES.map(c => `<button class="pill ${!isBinjiangRoute && state.category === c.key ? 'active' : ''}" data-category="${c.key}">${c.label}</button>`).join('');
  const listCategoryHtml = CATEGORIES.map(c => `<button class="pill ${state.category === c.key ? 'active' : ''}" data-category="${c.key}">${c.label}</button>`).join('');
  const strollHtml = `<button class="pill ${isBinjiangRoute ? 'active' : ''}" type="button" data-map-route="${BINJIANG_ROUTE_MODE}">漫步</button>`;
  $('#mapFilters').innerHTML = `${mapCategoryHtml}${strollHtml}`;
  $('#mapFilters').hidden = false;
  $('#listFilters').innerHTML = listCategoryHtml;

  const activeMapPill = $('#mapFilters .pill.active');
  if (activeMapPill) {
    const mapFilters = $('#mapFilters');
    mapFilters.scrollLeft = Math.max(0, activeMapPill.offsetLeft - (mapFilters.clientWidth - activeMapPill.clientWidth) / 2);
  }

  $$('#mapFilters [data-category]').forEach(btn => btn.addEventListener('click', () => setCategory(btn.dataset.category, 'map')));
  $('#mapFilters [data-map-route]')?.addEventListener('click', () => {
    state.mapMode = BINJIANG_ROUTE_MODE;
    state.category = 'all';
    state.selectedId = 'huangpu-riverside';
    renderRealMap({ resetCenter: true });
  });
  $$('#listFilters .pill').forEach(btn => btn.addEventListener('click', () => setCategory(btn.dataset.category, 'list')));
}

/*
  根据“当前分类”和“搜索关键词”过滤点位。
  列表页搜索时主要靠这个函数返回符合条件的点位。
*/
function filteredPoints() {
  const keyword = state.search.trim().toLowerCase();
  const matchedPoints = POINTS.filter(p => {
    const categoryOk = state.category === 'all' || p.category === state.category;
    const text = `${p.name} ${p.intro} ${p.address} ${getCategory(p.category).full}`.toLowerCase();
    const keywordOk = !keyword || text.includes(keyword);
    return categoryOk && keywordOk;
  });

  // 新增点位始终优先显示；同为新增或非新增时保持 points-data.js 中的原始顺序。
  return matchedPoints.sort((a, b) => Number(b.isNew === true) - Number(a.isNew === true));
}

/*
  渲染点位列表页。
  根据当前分类和搜索关键词，生成一张张点位卡片。
*/
function renderList() {
  renderFilterRows();
  const titleMap = {
    all: '全部点位',
    service: '便民服务',
    shopping: '生活购物',
    leisure: '休闲游玩',
    memory: '多稼记忆',
    bussiness: '商务办公'
  };
  $('#listTitle').textContent = titleMap[state.category] || '点位列表';

  const list = $('#placeList');
  const points = filteredPoints();
  if (!points.length) {
    list.innerHTML = `<div class="empty">没有找到相关点位。可以换个关键词，或点击上方分类重新筛选。</div>`;
    return;
  }
  list.innerHTML = points.map(point => {
    const category = getCategory(point.category);
    return `
      <article class="place-card">
        <div class="place-icon" style="background:${category.color}">${point.icon}</div>
        <div class="place-main">
          <h3>${point.name}${renderNewPointBadge(point)}<span class="tag ${point.category}">${category.full || category.label}</span></h3>
          <p>${point.intro}</p>
          <div class="place-lines">
            <span>⌖ ${point.address}</span>
            <span>◷ ${point.hours}</span>
          </div>
          <div class="place-actions">
            <button class="btn btn-mini btn-ghost" data-view-map="${point.id}">⌖ 查看地图</button>
            <button class="btn btn-mini btn-primary" data-nav="${point.id}">➤ 导航前往</button>
          </div>
        </div>
      </article>
    `;
  }).join('');

  $$('[data-nav]', list).forEach(btn => btn.addEventListener('click', () => navigateToPoint(getPoint(btn.dataset.nav))));
  $$('[data-view-map]', list).forEach(btn => btn.addEventListener('click', () => {
    state.mapReturnView = 'list';
    state.mapMode = null;
    state.selectedId = btn.dataset.viewMap;
    setView('map');
  }));
}

/*
  渲染便民电话页。
  根据 CONTACTS 数据生成电话卡片。
*/
function renderContacts() {
  const list = $('#contactList');
  list.innerHTML = CONTACTS.map(c => `
    <article class="contact-card">
      <div class="contact-icon" style="background:${c.color}">${c.icon}</div>
      <div>
        <h3>${c.name}</h3>
        <p>${c.desc}</p>
      </div>
      ${c.phones
        ? `<button class="btn btn-primary btn-mini contact-call-button" type="button" data-contact-choices="${c.id}">拨打</button>`
        : `<a class="btn btn-primary btn-mini" href="tel:${c.phone.replace(/\s/g, '')}">拨打</a>`}
    </article>
  `).join('');

  $$('[data-contact-choices]', list).forEach(button => {
    button.addEventListener('click', () => openPhoneChoices(button.dataset.contactChoices));
  });
}

/* 打开物业电话选择面板，用户选择具体物业后再进入系统拨号。 */
function openPhoneChoices(contactId) {
  const contact = CONTACTS.find(item => item.id === contactId);
  const lightbox = $('#phoneChoiceLightbox');
