// 仅调整点标记的屏幕显示位置（右/下为正），不改导航或地址解析坐标。
function getAmapMarkerOffset(point) {
  if (state.mapMode === BINJIANG_ROUTE_MODE) return [0, 0];
  const offset = point?.markerOffset;
  return Array.isArray(offset) && offset.length === 2
    && offset.every(value => Number.isFinite(value) && Math.abs(value) <= 96)
    ? [...offset]
    : [0, 0];
}

function renderAmapMarkers() {
  if (!amapRuntime.map || !amapRuntime.api) return;

  amapRuntime.markers.forEach(({ marker }) => marker.setMap(null));
  amapRuntime.markers.clear();

  const visiblePoints = getVisibleMapPoints();
  visiblePoints.forEach(point => {
    const element = createAmapMarkerElement(point);
    const marker = new amapRuntime.api.Marker({
      map: amapRuntime.map,
      position: [point.lng, point.lat],
      content: element,
      anchor: 'bottom-center',
      offset: new amapRuntime.api.Pixel(...getAmapMarkerOffset(point)),
      title: point.name,
      zIndex: point.id === state.selectedId ? 300 : 100
    });

    marker.on('click', () => selectRealMapPoint(point, true));
    amapRuntime.markers.set(point.id, { marker, element });
  });

  updateAmapMarkerSelection();
}

function drawAmapRoute(path, isWalkingRoute = true) {
  if (!amapRuntime.map || !amapRuntime.api || path.length < 2) return;
  if (amapRuntime.routeLine) {
    amapRuntime.routeLine.setMap(null);
    amapRuntime.routeLine = null;
  }
  amapRuntime.routeLine = new amapRuntime.api.Polyline({
    map: amapRuntime.map,
    path,
    zIndex: 60,
    strokeColor: isWalkingRoute ? BINJIANG_ROUTE_COLOR : '#a6b9a0',
    strokeOpacity: isWalkingRoute ? 0.98 : 0.85,
    strokeWeight: isWalkingRoute ? 8 : 6,
    isOutline: true,
    outlineColor: '#ffffff',
    borderWeight: 4,
    lineJoin: 'round',
    lineCap: 'round',
    strokeStyle: isWalkingRoute ? 'solid' : 'dashed',
    strokeDasharray: isWalkingRoute ? undefined : [8, 8],
    showDir: false
  });
}

function drawAmapRouteSpur(flowerBridgeCoordinate) {
  if (!amapRuntime.map || !amapRuntime.api) return;
  if (amapRuntime.routeSpur.length) amapRuntime.map.remove(amapRuntime.routeSpur);

  const path = [flowerBridgeCoordinate, ...BINJIANG_FLOWER_BRIDGE_SPUR];
  const metersPerLng = 111320 * Math.cos(flowerBridgeCoordinate[1] * Math.PI / 180);
  const lengths = path.slice(1).map(([lng, lat], index) => Math.hypot(
    (lng - path[index][0]) * metersPerLng,
    (lat - path[index][1]) * 111320
  ));
  const totalLength = lengths.reduce((sum, length) => sum + length, 0);
  const dotCount = Math.max(2, Math.round(totalLength / 30));
  amapRuntime.routeSpur = Array.from({ length: dotCount - 1 }, (_, index) => {
    let distance = totalLength * (index + 1) / dotCount;
    let segment = 0;
    while (segment < lengths.length - 1 && distance > lengths[segment]) {
      distance -= lengths[segment];
      segment += 1;
    }
    const progress = distance / lengths[segment];
    return new amapRuntime.api.CircleMarker({
      center: [
        path[segment][0] + (path[segment + 1][0] - path[segment][0]) * progress,
        path[segment][1] + (path[segment + 1][1] - path[segment][1]) * progress
      ],
      radius: 3.5,
      zIndex: 61,
      strokeColor: '#ffffff',
      strokeOpacity: 0.95,
      strokeWeight: 1.2,
      fillColor: BINJIANG_ROUTE_COLOR,
      fillOpacity: 1,
      bubble: true,
      clickable: false
    });
  });
  amapRuntime.map.add(amapRuntime.routeSpur);
}

function getAmapWalkingSegment(start, end) {
  return new Promise((resolve, reject) => {
    const walking = new amapRuntime.api.Walking({});
    walking.search(start, end, (status, result) => {
      const steps = result?.routes?.[0]?.steps;
      if (status !== 'complete' || !Array.isArray(steps) || !steps.length) {
        reject(new Error('步行路线规划未返回有效路径'));
        return;
      }
      const path = steps.flatMap(step => (Array.isArray(step.path) ? step.path : []).map(location => [
        Number(typeof location.getLng === 'function' ? location.getLng() : location[0]),
        Number(typeof location.getLat === 'function' ? location.getLat() : location[1])
      ])).filter(([lng, lat]) => hasCoordinatePair(lng, lat));
      if (path.length < 2) {
        reject(new Error('步行路线缺少有效坐标'));
        return;
      }
      resolve([start, ...path, end]);
    });
  });
}

async function renderAmapRoute() {
  const requestId = ++amapRuntime.routeRequestId;
  if (amapRuntime.routeLine) {
    amapRuntime.routeLine.setMap(null);
    amapRuntime.routeLine = null;
  }
  if (amapRuntime.routeSpur.length) amapRuntime.map?.remove(amapRuntime.routeSpur);
  amapRuntime.routeSpur = [];
  if (!amapRuntime.map || !amapRuntime.api || state.mapMode !== BINJIANG_ROUTE_MODE) return;

  const stops = getVisibleMapPoints();
  if (stops.length !== BINJIANG_ROUTE_POINT_IDS.length || !stops.every(hasAmapCoordinate)) return;
  const coordinates = stops.map(point => [Number(point.lng), Number(point.lat)]);
  drawAmapRouteSpur(coordinates[1]);
  if (amapRuntime.routePath) {
    drawAmapRoute(amapRuntime.routePath);
    return;
  }

  try {
    const waterfrontEnd = BINJIANG_WATERFRONT_PATH.at(-1);
    const segments = await Promise.all([
      getAmapWalkingSegment(waterfrontEnd, coordinates[2]),
      getAmapWalkingSegment(coordinates[2], coordinates[3])
    ]);
    if (requestId !== amapRuntime.routeRequestId || state.mapMode !== BINJIANG_ROUTE_MODE) return;
    amapRuntime.routePath = [
      coordinates[0],
      ...BINJIANG_WATERFRONT_PATH,
      ...segments[0].slice(1),
      ...segments[1].slice(1)
    ];
    drawAmapRoute(amapRuntime.routePath);
    fitAmapToBinjiangRoute();
  } catch (error) {
    if (requestId !== amapRuntime.routeRequestId || state.mapMode !== BINJIANG_ROUTE_MODE) return;
    drawAmapRoute([coordinates[0], ...BINJIANG_WATERFRONT_PATH, coordinates[2], coordinates[3]], false);
    showToast('步行规划暂不可用，当前主线为路线示意；请点击站点使用一键导航。');
    console.warn('滨江步行路线规划失败：', error);
  }
}

function fitAmapToBinjiangRoute() {
  if (!amapRuntime.map || state.mapMode !== BINJIANG_ROUTE_MODE) return;
  const overlays = [
    ...Array.from(amapRuntime.markers.values(), item => item.marker),
    amapRuntime.routeLine,
    ...amapRuntime.routeSpur
  ].filter(Boolean);
  if (overlays.length) amapRuntime.map.setFitView(overlays, false, [70, 44, 180, 44], 16);
}

function resetAmapToCommittee(selectPoint = false) {
  const centerPoint = getPoint(DUOJIA_CENTER_POINT_ID);
  if (amapRuntime.map) {
    amapRuntime.map.setZoomAndCenter(15.5, getAmapCenterCoordinate(), false, 260);
  }
  if (selectPoint && centerPoint) selectRealMapPoint(centerPoint, false);
}

async function ensureAmapMap({ resetCenter = false } = {}) {
  setAmapStatus('loading', '正在加载稼享地图');

  try {
    const AMap = await loadAmapApi();
    await resolveAmapPointCoordinates(AMap);

    if (!amapRuntime.map) {
      amapRuntime.map = new AMap.Map('duojiaMap', {
        center: getAmapCenterCoordinate(),
        zoom: 15.5,
        zooms: [13, 19],
        viewMode: '2D',
        mapStyle: 'amap://styles/whitesmoke',
        features: ['bg', 'road', 'building'],
        showLabel: true,
        rotateEnable: false,
        pitchEnable: false,
        resizeEnable: true
      });
      amapRuntime.map.on('click', closeRealMapSheet);
    }

    renderAmapMarkers();
    renderAmapRoute();
    if (state.mapMode === BINJIANG_ROUTE_MODE) fitAmapToBinjiangRoute();
    else if (resetCenter) resetAmapToCommittee(false);
    requestAnimationFrame(() => amapRuntime.map?.resize());
    document.querySelector('#locateBtn').hidden = state.mapMode === BINJIANG_ROUTE_MODE;
    setAmapStatus('ready');

    if (amapRuntime.fallbackCount && state.mapMode !== BINJIANG_ROUTE_MODE) {
      showToast(`${POINTS.length} 个点位已显示，其中 ${amapRuntime.fallbackCount} 个使用备用位置，可在 points-data.js 中补充 lng/lat。`);
    }
  } catch (error) {
    const isMissingConfig = error?.message === 'AMAP_CONFIG_MISSING';
    setAmapStatus(
      'error',
      isMissingConfig ? '请先填写高德地图配置' : '地图暂时无法加载',
      isMissingConfig
        ? '打开 <code>amap.config.js</code>，填写 Web 端 Key 和安全密钥后刷新页面。'
        : '请检查网络、Key 的域名白名单和安全密钥配置。'
    );
    document.querySelector('#locateBtn').hidden = true;
    console.error('高德地图初始化失败：', error);
  }
}

function renderRealMap(options = {}) {
  renderFilterRows();
  closeRealMapSheet();

  $('#mapTitle').textContent = '生活地图';
  const visiblePoints = getVisibleMapPoints();
  if (!visiblePoints.some(point => point.id === state.selectedId)) {
    state.selectedId = visiblePoints[0]?.id || DUOJIA_CENTER_POINT_ID;
  }

  const selectedPoint = visiblePoints.find(point => point.id === state.selectedId) || null;
  if (selectedPoint) renderMapSheet(selectedPoint);
  void ensureAmapMap(options);
}

function closeRealMapSheet() {
  const sheet = document.querySelector('#mapSheet');
  if (sheet) sheet.classList.remove('is-open');
}

function selectRealMapPoint(point, panToPoint = false) {
  if (!point) return null;
  state.selectedId = point.id;
  updateAmapMarkerSelection();
  if (panToPoint && amapRuntime.map && hasAmapCoordinate(point)) {
    amapRuntime.map.panTo([point.lng, point.lat], 260);
  }
  return renderMapSheet(point);
}

// 短评直接展示在点位卡片中；不会参与详情折叠或地图点位数据导出。
function renderPointReview(point) {
  const data = window.POINT_REVIEWS_DATA;
  const entries = data?.entries;
  if (!point || !entries || !Object.prototype.hasOwnProperty.call(entries, point.id)) return '';

  const review = entries[point.id];
  if (!review || !Number.isInteger(review.rating) || review.rating < 1 || review.rating > 5
      || typeof review.text !== 'string' || !review.text.trim()) return '';

  const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[char]));

  return `
    <aside class="map-point-review" aria-label="${escape(point.name)}的个人探店笔记">
      <div class="map-point-review__head">
        <h4 class="map-point-review__title">${escape(data.label || '邻里探店笔记')}</h4>
        <span class="map-point-review__score" aria-label="个人评分${review.rating}分，满分5分">个人 ${review.rating} / 5</span>
      </div>
      <p class="map-point-review__text">${escape(review.text)}</p>
      <p class="map-point-review__disclaimer">${escape(data.disclaimer || '个人体验，仅供参考，非综合评分')}</p>
    </aside>
  `;
}

// 只负责生成详情内容、绑定详情按钮事件并打开详情卡片。
function renderMapSheet(point) {
if (!point) return null;

const sheet = document.querySelector("#mapSheet");
if (!sheet) return null;

const category = getCategory(point.category);
const locations = Array.isArray(point.locations) ? point.locations : [];

if (locations.length) {
  sheet.innerHTML = `
    <span class="sheet-selection-label"></span>
    <div class="cluster-sheet-card">
      <div class="sheet-title-row">
        <h3>${point.name}</h3>
        ${renderNewPointBadge(point)}
        <span class="tag ${point.category}">${locations.length}个地点</span>
      </div>
      <p class="cluster-sheet-intro">地图上合并为一个点位，请在下方选择具体目的地。</p>
      <div class="cluster-location-list">
        ${locations.map((location, index) => `
          <article class="cluster-location">
            <span class="cluster-location-index">${index + 1}</span>
            <div class="cluster-location-info">
              <strong>${location.name}</strong>
              <small>${location.address || '暂无详细地址'}</small>
            </div>
            <button class="cluster-nav-btn" type="button" data-cluster-nav="${index}" aria-label="导航到${location.name}">导航</button>
          </article>
        `).join('')}
      </div>
      <div class="cluster-sheet-actions">
        <button class="btn btn-ghost" id="copyClusterBtn"><span aria-hidden="true">⧉</span> 复制三个地点名称</button>
      </div>
    </div>
  `;

  sheet.querySelectorAll('[data-cluster-nav]').forEach(button => {
    button.addEventListener('click', () => {
      const location = locations[Number(button.dataset.clusterNav)];
      if (!location) return;
      showToast(`正在打开${location.name}`);
      navigateToPoint(location);
    });
  });

  sheet.querySelector('#copyClusterBtn').addEventListener('click', async () => {
    const names = locations.map(location => location.name).join('、');
    try {
      await navigator.clipboard.writeText(names);
      showToast('已复制三个地点名称');
    } catch {
      showToast(names);
    }
  });

  requestAnimationFrame(() => sheet.classList.add('is-open'));
  return sheet;
}

sheet.innerHTML = `
  <span class="sheet-selection-label"></span>
  <div class="map-sheet-compact ${point.image ? '' : 'no-photo'}">
    ${point.image ? `
      <figure class="map-place-photo">
        <img src="${point.image}" alt="${point.imageAlt || point.name}">
        <button class="map-place-photo-zoom" type="button"></button>
        <div class="map-place-photo-fallback" hidden>
          <span aria-hidden="true">▣</span>
          <strong>${point.name}</strong>
          <small>请将实景照片放入指定素材目录</small>
        </div>
        <figcaption>${point.imageCaption || point.name}</figcaption>
      </figure>
    ` : ''}
    <div class="map-sheet-summary">
      <div class="sheet-title-row">
        <h3>${point.name}</h3>
        ${renderNewPointBadge(point)}
        <span class="tag ${point.category}">${category.full || category.label}</span>
      </div>
      ${point.description ? `<p class="sheet-description">${point.description}</p>` : ''}
      <p class="sheet-address"><span aria-hidden="true">⌖</span> ${point.address || "暂无详细地址，可后续补充。"}</p>
      ${point.imageCredit ? `<p class="map-photo-credit">照片：<a href="${point.imageSource}" target="_blank" rel="noopener noreferrer">${point.imageCredit}</a> · <a href="${point.imageLicenseUrl}" target="_blank" rel="noopener noreferrer">${point.imageLicense}</a> · 已缩放</p>` : ''}
      <div class="map-sheet-compact-actions">
        <button class="sheet-details-btn" id="detailsBtn" type="button" aria-expanded="false">查看详情 <span aria-hidden="true">›</span></button>
        <button class="btn btn-primary" id="navBtn"><span aria-hidden="true">➤</span> 一键导航</button>
      </div>
    </div>
    ${renderPointReview(point)}
  </div>
  <div class="sheet-detail-extra" id="sheetDetailExtra" hidden>
    <span><b>完整地址</b>${point.address || "暂无详细地址"}</span>
    <span><b>路线提示</b>点击一键导航，可在高德地图中查看步行路线。</span>
  </div>
`;

const navButton = sheet.querySelector("#navBtn");
const detailsButton = sheet.querySelector("#detailsBtn");
const detailExtra = sheet.querySelector("#sheetDetailExtra");
const placePhoto = sheet.querySelector(".map-place-photo img");
const photoZoom = sheet.querySelector(".map-place-photo-zoom");

if (photoZoom) {
  photoZoom.setAttribute('aria-label', `放大查看${point.name}照片`);
  photoZoom.dataset.activityPhoto = point.image;
  photoZoom.dataset.activityPhotoAlt = point.imageAlt || point.name;
  photoZoom.dataset.activityPhotoTitle = point.imageCaption || point.name;
}

if (placePhoto) {
  placePhoto.addEventListener("error", () => {
    placePhoto.hidden = true;
    if (photoZoom) photoZoom.disabled = true;
    const fallback = sheet.querySelector(".map-place-photo-fallback");
    if (fallback) fallback.hidden = false;
  });
}

navButton.addEventListener("click", () => {
  navigateToPoint(point);
});

detailsButton.addEventListener("click", () => {
  const isExpanded = detailsButton.getAttribute("aria-expanded") === "true";
  detailsButton.setAttribute("aria-expanded", String(!isExpanded));
  detailExtra.hidden = isExpanded;
  detailsButton.innerHTML = isExpanded
    ? '查看详情 <span aria-hidden="true">›</span>'
    : '收起详情 <span aria-hidden="true">⌃</span>';
});

requestAnimationFrame(() => {
  sheet.classList.add("is-open");
});

return sheet;
  }

/*
  初始化函数。
  页面第一次打开时，只执行一次。
  它会把所有数据渲染到页面上，并绑定各种点击事件。
*/
function init() {
  setupMoreRoutesDialog();
  setupGuideGallery();
  setupActivityPage();
  setupActivityUpload();
  setupHomeRegistration();
  $$('[data-phone-choice-close]').forEach(button => button.addEventListener('click', closePhoneChoices));
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') closePhoneChoices();
  });
  renderQuickEntries();
  renderFilterRows();
  renderList();
  renderContacts();
  bindEvents();
}

// 启动整个网页。
init();
